 const mappings=groups.map(([key,keys,facets])=>registerServiceGroup(dataset,key,keys,facets,{uuid:uuids[key],activityId:id}).mapping)
 const owners=new Map(groups.flatMap(([key,keys])=>keys.map(activity=>[activity,key])))
 for(const spec of specs){const mapping=mappings.find(item=>item.key===owners.get(spec.key));authorProfessionActivity(dataset,{...spec,id:id(spec.key),supporting_sources:[{title:'ESCO 1.2.1: '+dataset.capabilities.find(node=>node.id===mapping.skill_id).label,url:mapping.skill_id},...(['mailintegrity','packagetypes'].includes(owners.get(spec.key))?[packingSource]:[]),...(owners.get(spec.key)==='mailingsystems'?[trackingSource,tableSource]:[])]})}
 for(const mapping of mappings)for(const to of mapping.activity_ids)if(!dataset.decompositions.some(edge=>edge.type==='decomposes_into'&&edge.from===mapping.skill_id&&edge.to===to))dataset.decompositions.push({from:mapping.skill_id,to,type:'decomposes_into',completion_requirement:'required',validation:'proposed',source:professionSource})
 return mappings
